import 'package:flutter/foundation.dart'; import 'package:permission_handler/permission_handler.dart'; import '../../platform/eye_control_platform.dart';
class PermissionProvider extends ChangeNotifier { PermissionProvider({EyeControlPlatform? platform}):_platform=platform??EyeControlPlatform(); final EyeControlPlatform _platform; bool camera=false,overlay=false,accessibility=false,loading=false; String? error; bool get ready=>camera&&overlay&&accessibility;
Future<void> refresh() async { loading=true; notifyListeners(); try{camera=await Permission.camera.isGranted; overlay=await _platform.isOverlayGranted(); accessibility=await _platform.isAccessibilityEnabled(); error=null;}catch(e){error=e.toString();} loading=false; notifyListeners(); }
Future<void> requestCamera() async {await Permission.camera.request();await refresh();} Future<void> requestOverlay() async{await _platform.requestOverlayPermission();await refresh();} Future<void> requestAccessibility() async{await _platform.requestAccessibilitySettings();await refresh();}}